-- =============================================================================
-- FactSync Chile: Spanish and English Wikipedia articles of every current comuna.
-- GENERATED by scripts/build_wikipedia_sql.py; regenerate rather than edit.
-- Run as an ADMIN user after 01 and 02. One statement per request.
--
-- Sources
--   Wikidata sitelinks: comuna item, CUT and article titles (CC0).
--   Wikipedia ES/EN: latest revision wikitext via the MediaWiki API, in batches
--     of up to 50 titles (294 ES, 287 EN articles). Text is CC BY-SA 4.0.
--   Wikimedia requires an identifying User-Agent: filled from ZETARIS_USER_AGENT.
-- =============================================================================

CREATE LIGHTNING REST TABLE wikidata_comunas_raw FROM FACTSYNC_REST REQUEST(
    endpoint "https://query.wikidata.org/sparql?query=SELECT+%3Fcomuna+%3Fcut+%3Flabel_es+%3Fes_title+%3Fen_title+WHERE+%7B+%3Fcomuna+wdt%3AP31+wd%3AQ1840161.+FILTER+NOT+EXISTS+%7B+%3Fcomuna+wdt%3AP576+%3Fdissolved+%7D+OPTIONAL+%7B+%3Fcomuna+wdt%3AP6929+%3Fcut+%7D+OPTIONAL+%7B+%3Fcomuna+rdfs%3Alabel+%3Flabel_es+FILTER%28lang%28%3Flabel_es%29%3D%27es%27%29+%7D+OPTIONAL+%7B+%3Fes+schema%3Aabout+%3Fcomuna%3B+schema%3AisPartOf+%3Chttps%3A%2F%2Fes.wikipedia.org%2F%3E%3B+schema%3Aname+%3Fes_title+%7D+OPTIONAL+%7B+%3Fen+schema%3Aabout+%3Fcomuna%3B+schema%3AisPartOf+%3Chttps%3A%2F%2Fen.wikipedia.org%2F%3E%3B+schema%3Aname+%3Fen_title+%7D+%7D&format=json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
    user-agent "YOUR_APP_NAME YOUR_CONTACT_EMAIL"
) BODY ();

CREATE OR REPLACE SCHEMASTORE VIEW wikidata_comunas WITH CONTAINER factsync AS
SELECT
    b.comuna.value AS wikidata_item,
    b.cut.value AS cut,
    b.label_es.value AS label_es,
    b.es_title.value AS es_title,
    b.en_title.value AS en_title
FROM factsync_rest.wikidata_comunas_raw
LATERAL VIEW explode(results.bindings) AS b;

