CREATE OR REPLACE SCHEMASTORE VIEW enwiki_articles WITH CONTAINER factsync AS
SELECT w.cut, w.wikidata_item, a.pageid, a.title, a.revid, a.revision_timestamp, a.wikitext
FROM (
SELECT p.pageid, p.title, p.revisions[0].revid AS revid, p.revisions[0].timestamp AS revision_timestamp,
       p.revisions[0].slots.main.content AS wikitext
FROM factsync_rest.enwiki_batch_01_raw LATERAL VIEW explode(query.pages) AS p
UNION ALL
SELECT p.pageid, p.title, p.revisions[0].revid AS revid, p.revisions[0].timestamp AS revision_timestamp,
       p.revisions[0].slots.main.content AS wikitext
FROM factsync_rest.enwiki_batch_02_raw LATERAL VIEW explode(query.pages) AS p
UNION ALL
SELECT p.pageid, p.title, p.revisions[0].revid AS revid, p.revisions[0].timestamp AS revision_timestamp,
       p.revisions[0].slots.main.content AS wikitext
FROM factsync_rest.enwiki_batch_03_raw LATERAL VIEW explode(query.pages) AS p
UNION ALL
SELECT p.pageid, p.title, p.revisions[0].revid AS revid, p.revisions[0].timestamp AS revision_timestamp,
       p.revisions[0].slots.main.content AS wikitext
FROM factsync_rest.enwiki_batch_04_raw LATERAL VIEW explode(query.pages) AS p
UNION ALL
SELECT p.pageid, p.title, p.revisions[0].revid AS revid, p.revisions[0].timestamp AS revision_timestamp,
       p.revisions[0].slots.main.content AS wikitext
FROM factsync_rest.enwiki_batch_05_raw LATERAL VIEW explode(query.pages) AS p
UNION ALL
SELECT p.pageid, p.title, p.revisions[0].revid AS revid, p.revisions[0].timestamp AS revision_timestamp,
       p.revisions[0].slots.main.content AS wikitext
FROM factsync_rest.enwiki_batch_06_raw LATERAL VIEW explode(query.pages) AS p
) a
LEFT JOIN factsync.wikidata_comunas w ON w.en_title = a.title;
